double s2;
if ((sigma == NULL) || (shadow == NULL) || (switched == NULL)) {
    return ADCS_E_NULL;
}
if (!adcs_is_finite_vec3(sigma)) {
    return ADCS_E_NOT_FINITE;
}
s2 = adcs_vec3_dot(sigma, sigma);
if (s2 > 1.0) {
    *shadow = adcs_vec3_scale(sigma, -1.0 / s2);
    *switched = 1;
} else {
    *shadow = *sigma;
    *switched = 0;
}
return ADCS_OK;
}

